// src/Socket.jsx
import React, { useEffect, useState } from "react";
import { io } from "socket.io-client";

const socket = io("http://localhost:5000");

export default function Socket({ currentUser }) {
  const [allUsers, setAllUsers] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [chatMessages, setChatMessages] = useState([]);
  const [message, setMessage] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    if (!currentUser) return;

    socket.emit("set username", currentUser);

    socket.on("all users", (users) => {
      const filtered = users.filter((u) => u.username !== currentUser);
      setAllUsers(filtered);
    });

    socket.on("load messages", (msgs) => {
      setChatMessages(msgs);
    });

    socket.on("private message", (msg) => {
      setChatMessages((prev) => [...prev, msg]);
    });

    return () => {
      socket.off("all users");
      socket.off("load messages");
      socket.off("private message");
    };
  }, [currentUser]);

  const sendMessage = (e) => {
    e.preventDefault();
    if (!message || !selectedUser) return;

    const msg = {
      from: currentUser,
      to: selectedUser,
      content: message,
      timestamp: new Date(),
    };

    socket.emit("private message", msg);
    setMessage("");
  };

  const filteredUsers = allUsers.filter((user) =>
    user.username.toLowerCase().includes(search.toLowerCase())
  );

  const filteredMessages = chatMessages.filter(
    (m) =>
      (m.from === currentUser && m.to === selectedUser) ||
      (m.from === selectedUser && m.to === currentUser)
  );

  return (
    <div style={styles.chatContainer}>
      <h2 style={styles.title}>💬 Messenger Chat</h2>

      <div style={styles.box}>
        <label style={styles.label}>🔍 Search Users</label>
        <input
          placeholder="Search users..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          style={styles.input}
        />
        <div style={styles.userList}>
          {filteredUsers.length === 0 ? (
            <p style={styles.noUser}>No users found.</p>
          ) : (
            filteredUsers.map((user) => (
              <div
                key={user.username}
                style={{
                  ...styles.userItem,
                  backgroundColor:
                    selectedUser === user.username ? "#e0e0ff" : "#f5f5f5",
                }}
                onClick={() => setSelectedUser(user.username)}
              >
                <span>
                  {user.username}{" "}
                  {user.online ? "🟢" : "⚪"}
                </span>
              </div>
            ))
          )}
        </div>

        {selectedUser && (
          <>
            <div style={styles.chatBox}>
              {filteredMessages.map((msg, idx) => (
                <div
                  key={idx}
                  style={{
                    ...styles.msg,
                    alignSelf:
                      msg.from === currentUser ? "flex-end" : "flex-start",
                    backgroundColor:
                      msg.from === currentUser ? "#d1e7dd" : "#f8d7da",
                  }}
                >
                  <strong>{msg.from === currentUser ? "You" : msg.from}</strong>:{" "}
                  {msg.content}
                </div>
              ))}
            </div>
            <form onSubmit={sendMessage} style={styles.form}>
              <input
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Type a message..."
                style={styles.msgInput}
              />
              <button type="submit" style={styles.sendBtn}>
                ➤
              </button>
            </form>
          </>
        )}
      </div>
    </div>
  );
}

const styles = {
  chatContainer: {
    marginTop: 30,
  },
  title: {
    textAlign: "center",
    marginBottom: 10,
  },
  box: {
    maxWidth: 500,
    margin: "0 auto",
    borderRadius: 10,
    padding: 20,
    background: "#fff",
    boxShadow: "0 0 10px rgba(0,0,0,0.1)",
  },
  label: {
    fontWeight: "bold",
    marginBottom: 5,
    display: "block",
  },
  input: {
    width: "100%",
    padding: 8,
    marginBottom: 10,
    borderRadius: 5,
    border: "1px solid #ccc",
  },
  userList: {
    maxHeight: 150,
    overflowY: "auto",
    marginBottom: 10,
    border: "1px solid #ccc",
    borderRadius: 5,
  },
  userItem: {
    padding: 8,
    cursor: "pointer",
    borderBottom: "1px solid #eee",
  },
  noUser: {
    padding: 8,
    textAlign: "center",
    color: "#888",
  },
  chatBox: {
    minHeight: 150,
    maxHeight: 250,
    overflowY: "auto",
    display: "flex",
    flexDirection: "column",
    gap: 5,
    marginBottom: 10,
    padding: 10,
    backgroundColor: "#fafafa",
    borderRadius: 5,
    border: "1px solid #ccc",
  },
  msg: {
    padding: 8,
    borderRadius: 10,
    maxWidth: "70%",
  },
  form: {
    display: "flex",
    gap: 10,
  },
  msgInput: {
    flex: 1,
    padding: 8,
    borderRadius: 5,
    border: "1px solid #ccc",
  },
  sendBtn: {
    padding: "0 16px",
    backgroundColor: "#4a90e2",
    color: "white",
    border: "none",
    borderRadius: 5,
    cursor: "pointer",
  },
};
